mapper.select:
SELECT COUNT(1)
FROM feedback f
WHERE f.merchant_id = #{merchantId}

    AND f.dish_id = #{dishId}


    AND f.feedback_type = #{feedbackType}


    AND f.status = #{status}

SELECT f.id, f.user_id AS userId, su.nickname AS userNickname, f.target_type AS targetType, f.dish_id AS targetId, f.dish_id AS dishId, d.name AS dishName, f.feedback_type AS feedbackType, f.content, f.status, f.reply_content AS replyContent, f.replied_by AS repliedBy, f.replied_at AS repliedAt, f.created_at AS createdAt FROM feedback f INNER JOIN sys_user su ON su.id = f.user_id INNER JOIN dish d ON d.id = f.dish_id WHERE f.merchant_id = #{merchantId}
AND f.dish_id = #{dishId}
AND f.feedback_type = #{feedbackType}
AND f.status = #{status}
ORDER BY f.created_at DESC, f.id DESC LIMIT #{offset}, #{size}
